// W2-E sanctions screen on the server: OFAC SDN list (lib/ofac-sdn.ts, generated by scripts/ofac-sdn.mjs).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { POST as createGroupRoute } from "@/app/api/v1/groups/route";
import { POST as createInvoiceRoute } from "@/app/api/v1/invoices/route";
import { POST as createRequestRoute } from "@/app/api/v1/requests/route";
import { ErrorResponse } from "@/lib/contract";
import { OFAC_SDN } from "@/lib/ofac-sdn";
import { requireNotSanctioned, sdnEntry } from "@/lib/sanctions";

const LISTED = "6wjqWWra8ombzaw6VHrG5xpQ972jCYF6bbHiFCbWmr4U"; // SDN, program SDGT

test("the server's snapshot is byte-identical to the plugin's", () => {
  assert.equal(readFileSync(new URL("../lib/ofac-sdn.ts", import.meta.url), "utf8"), readFileSync(new URL("../../plugin/src/ofac-sdn.ts", import.meta.url), "utf8"));
  assert.equal(OFAC_SDN.addresses.filter((e) => e.kind === "solana").length, 4);
});

test("requireNotSanctioned: SDN addresses throw blocked (EVM any case); others pass", () => {
  assert.throws(() => requireNotSanctioned(LISTED), (e: Error & { code?: string }) => e.code === "blocked" && /OFAC sanctions list \(SDN entry .+, SDGT; list of \d{4}-\d{2}-\d{2}\)/.test(e.message));
  const evm = OFAC_SDN.addresses.find((e) => e.kind === "evm")!.address;
  assert.equal(sdnEntry(evm.toUpperCase().replace("0X", "0x"))?.address, evm);
  assert.doesNotThrow(() => requireNotSanctioned("FN6G4CQkrM55pnT4npu1U8xegZk7AMnp3ApGvkM4cbvs"));
});

test("every create route answers 403 blocked for an SDN recipient, before any database or DNS work", async () => {
  const realFetch = globalThis.fetch;
  globalThis.fetch = (() => { throw new Error("no network: the screen runs first"); }) as typeof fetch;
  try {
    const post = (route: (r: Request) => Promise<Response>, path: string, body: unknown) =>
      route(new Request(`https://owed.example${path}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }));
    for (const [route, path, body] of [
      [createRequestRoute, "/api/v1/requests", { recipient: LISTED, amount: "1", from_domain: "example.com" }],
      [createGroupRoute, "/api/v1/groups", { recipient: LISTED, total: "2", token: "USDC", title: "t", people: [{ name: "a" }, { name: "b" }] }],
      [createInvoiceRoute, "/api/v1/invoices", { recipient: LISTED, token: "USDC", business_name: "b", client_name: "c", items: [{ description: "x", unit_price: "1" }], due_date: "2030-01-01" }],
    ] as const) {
      const res = await post(route, path, body);
      assert.equal(res.status, 403, path);
      const err = ErrorResponse.parse(await res.json()).error;
      assert.equal(err.code, "blocked");
      assert.match(err.message, /OFAC sanctions list/);
    }
  } finally {
    globalThis.fetch = realFetch;
  }
});
